<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();if(isset($_GET['id'],$_GET['status'])){$allowed=['Pending','Confirmed','Completed','Cancelled','No-show'];if(in_array($_GET['status'],$allowed,true)){ $s=$pdo->prepare('UPDATE appointments SET status=? WHERE id=?');$s->execute([$_GET['status'],(int)$_GET['id']]);audit('status_change','appointment',(int)$_GET['id'],$_GET['status']);flash('Appointment updated.');redirect('appointments.php');}}$rows=$pdo->query('SELECT a.*,d.name department FROM appointments a LEFT JOIN departments d ON d.id=a.department_id ORDER BY a.appointment_date DESC,a.appointment_time DESC LIMIT 200')->fetchAll();admin_header('Appointments','appointments.php');?><div class="pagehead"><div><h1>Appointments</h1><div class="muted">Review and confirm patient appointment requests.</div></div></div><div class="card table-wrap"><table class="table"><tr><th>Date</th><th>Patient</th><th>Phone</th><th>Department</th><th>Reason</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['appointment_date'].' '.($r['appointment_time']??''))?></td><td><?=e($r['patient_name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['department'])?></td><td><?=e($r['reason'])?></td><td><span class="badge <?=in_array($r['status'],['Confirmed','Completed'])?'ok':($r['status']==='Cancelled'?'bad':'warn')?>"><?=e($r['status'])?></span></td><td class="actions"><a class="btn secondary" href="?id=<?=$r['id']?>&status=Confirmed">Confirm</a><a class="btn secondary" href="?id=<?=$r['id']?>&status=Completed">Complete</a><a class="btn danger" href="?id=<?=$r['id']?>&status=Cancelled">Cancel</a></td></tr><?php endforeach;?></table></div><?php admin_footer();
